<?php
namespace App\Http\Controllers;
use App\Models\{Company,Account};use Illuminate\Http\Request;
class SettingsController {public function edit(){return view('settings.index',['company'=>auth()->user()->company,'accounts'=>Account::forCompany(auth()->user()->company_id)->where('is_postable',1)->orderBy('code')->get()]);}public function update(Request $r){$c=$r->user()->company;$d=$r->validate(['name'=>'required|string|max:255','tax_number'=>'nullable|string|max:100','registration_number'=>'nullable|string|max:100','phone'=>'nullable|string|max:50','email'=>'nullable|email','address'=>'nullable|string|max:500','retained_earnings_account_id'=>'required|integer','fx_gain_account_id'=>'required|integer','fx_loss_account_id'=>'required|integer','ar_control_account_id'=>'required|integer','ap_control_account_id'=>'required|integer','sales_tax_account_id'=>'required|integer','purchase_tax_account_id'=>'required|integer']);foreach(array_filter($d,fn($v,$k)=>str_ends_with($k,'_account_id'),ARRAY_FILTER_USE_BOTH) as $id)Account::forCompany($c->id)->where('is_postable',1)->findOrFail($id);$c->update($d);return back()->with('ok','Company accounting settings updated.');}}
